//! S/MIME trust anchors (t32-e41, DA45): the bundled Mozilla email-protection root
//! set (on by default, can be turned off per domain), administrator roots per
//! domain or global, and certificates the user trusts.
//!
//! The bundled set is `data/smime-roots/roots.der` (concatenated DER) with
//! `roots.json` (snapshot date, source digest, per-root email distrust date),
//! generated by `scripts/smime/gen-roots.mjs` from NSS `certdata.txt` (MPL-2.0).
//! `webpki-roots` is not used: it carries the TLS trust bit, not email protection.

use std::sync::OnceLock;

use der::{Decode, Reader, SliceReader};
use serde::{Deserialize, Serialize};
use x509_cert::Certificate;

use crate::pkix::path::{Anchor, AnchorSource, fingerprint, parse_certs};

const ROOTS_DER: &[u8] = include_bytes!("../data/smime-roots/roots.der");
const ROOTS_META: &str = include_str!("../data/smime-roots/roots.json");

/// What the bundled root set is, for the admin view.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RootSetInfo {
    /// The date `certdata.txt` was taken (YYYY-MM-DD).
    pub snapshot: String,
    pub count: usize,
    pub source: String,
    pub source_sha256: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Meta {
    snapshot: String,
    source: String,
    source_sha256: String,
    count: usize,
    roots: Vec<MetaRoot>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct MetaRoot {
    sha256: String,
    email_distrust_after: Option<u64>,
}

fn meta() -> &'static Meta {
    static META: OnceLock<Meta> = OnceLock::new();
    META.get_or_init(|| serde_json::from_str(ROOTS_META).expect("bundled roots.json parses"))
}

/// The bundled Mozilla email-protection roots, parsed once.
pub fn mozilla_roots() -> &'static [Anchor] {
    static ROOTS: OnceLock<Vec<Anchor>> = OnceLock::new();
    ROOTS.get_or_init(|| {
        let m = meta();
        let mut out = Vec::with_capacity(m.count);
        let Ok(mut r) = SliceReader::new(ROOTS_DER) else {
            return out;
        };
        while !r.is_finished() {
            let Ok(cert) = Certificate::decode(&mut r) else {
                break;
            };
            let fp = fingerprint(&cert);
            let distrust_after = m
                .roots
                .iter()
                .find(|x| x.sha256.eq_ignore_ascii_case(&fp))
                .and_then(|x| x.email_distrust_after);
            out.push(Anchor {
                cert,
                source: AnchorSource::Mozilla,
                distrust_after,
            });
        }
        out
    })
}

/// Snapshot date, size and origin of the bundled set.
pub fn root_set_info() -> RootSetInfo {
    let m = meta();
    RootSetInfo {
        snapshot: m.snapshot.clone(),
        count: mozilla_roots().len(),
        source: m.source.clone(),
        source_sha256: m.source_sha256.clone(),
    }
}

/// Which anchors apply to one check.
#[derive(Debug, Clone, Default)]
pub struct TrustConfig {
    /// Certificates (roots or leaves) the user trusts: PEM or DER each.
    pub user: Vec<Vec<u8>>,
    /// Administrator roots for the domain and global ones: PEM or DER each.
    pub admin: Vec<Vec<u8>>,
    /// Include the bundled Mozilla set (the default; a domain may turn it off).
    pub mozilla: bool,
}

impl TrustConfig {
    /// The default: the bundled set only.
    pub fn bundled() -> Self {
        TrustConfig {
            user: Vec::new(),
            admin: Vec::new(),
            mozilla: true,
        }
    }

    /// The anchors, user ones first.
    pub fn anchors(&self) -> Vec<Anchor> {
        let mut out = Vec::new();
        for (list, source) in [
            (&self.user, AnchorSource::User),
            (&self.admin, AnchorSource::Admin),
        ] {
            for bytes in list {
                for cert in parse_certs(bytes) {
                    out.push(Anchor {
                        cert,
                        source,
                        distrust_after: None,
                    });
                }
            }
        }
        if self.mozilla {
            out.extend(mozilla_roots().iter().cloned());
        }
        out
    }
}

/// Parse one certificate from PEM or DER (helper for callers holding bytes).
pub fn certificate(bytes: &[u8]) -> Option<Certificate> {
    let trimmed = bytes.trim_ascii_start();
    if trimmed.starts_with(b"-----BEGIN") {
        parse_certs(trimmed).into_iter().next()
    } else {
        Certificate::from_der(bytes).ok()
    }
}
